// tvuMakeTwoAudioFixture mirrors the repro's makeTwoAudioFixture
// (internal/stream/pack_multi_audio_test.go — package stream, not importable):
// one tiny MKV with an h264 video track and TWO AAC audio tracks — the
// dual-audio muxed shape, both audio streams embedded in the source, no
// sidecars — with the same keyframing so the pack segments the way real media
// does. Returns the absolute path. No network, in-process.
func tvuMakeTwoAudioFixture(t *testing.T, dir string, dur time.Duration) string {
	t.Helper()
	out := filepath.Join(dir, "Dual Audio.mkv")
	args := []string{
		"-nostdin", "-y",
		"-f", "lavfi", "-i", "testsrc2=size=128x72:rate=10:duration=" + secs(dur),
		"-f", "lavfi", "-i", "sine=frequency=440:sample_rate=44100:duration=" + secs(dur),
		"-f", "lavfi", "-i", "sine=frequency=880:sample_rate=44100:duration=" + secs(dur),
		"-map", "0:v", "-map", "1:a", "-map", "2:a",
		"-c:v", "libx264", "-pix_fmt", "yuv420p", "-force_key_frames", "expr:gte(t,n_forced*2)", "-c:a", "aac",
		out,
	}
	if b, err := exec.Command("ffmpeg", args...).CombinedOutput(); err != nil {
		t.Fatalf("two-audio fixture generation failed: %v: %s", err, b)
	}
	return out
}

// tvuTwoAudioFacts is the honest stored-fact shape of that fixture (h264 High
// + two aac audio streams in a Matroska container — what a real scan stamps
// for the dual-audio muxed source). The layout decision itself does NOT read
// these: Pack re-probes the FILE once at build time (D1 — the file is ground
// truth), so the joint stays honest even though the facts ride along.
func tvuTwoAudioFacts() map[string]any {
	return map[string]any{
		"format": map[string]any{"format_name": "matroska,webm", "duration": "5.000000"},
		"streams": []any{
			map[string]any{"codec_type": "video", "codec_name": "h264", "profile": "High"},
			map[string]any{"codec_type": "audio", "codec_name": "aac"},
			map[string]any{"codec_type": "audio", "codec_name": "aac"},
		},
	}
}

// tvuDescriptor is the descriptor wire shape decoded from the SERVED bytes —
// codecs and layout stay raw so the joint asserts the wire's presence and
// values exactly as the SPA consumes them (a typed Go string would silently
// accept an empty string where the contract wants the key present; a missing
// key must read as absent).
type tvuDescriptor struct {
	Mode       string          `json:"mode"`
	State      string          `json:"state"`
	PlayURL    string          `json:"play_url"`
	Codecs     json.RawMessage `json:"codecs"`
	Layout     json.RawMessage `json:"layout"`
	Sections   json.RawMessage `json:"sections"`
	Voiceovers json.RawMessage `json:"voiceovers"`
}

// tvuServer boots a real api+web router over the world with the descriptor
// closure in miniature (decision_log.go's playbackDescriptor — Describe's
// FULL return set threaded, Layout riding into api.Playback exactly as the
// production closure threads it). Returns the server's base URL.
func tvuServer(t *testing.T, w *pbWorld) string {
	t.Helper()
	apiH := api.New(api.Deps{
		AdminToken: w.token,
		Store:      w.st,
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			row, err := w.st.GetItem(ctx, itemID)
			if err != nil {
				return api.Playback{}, err // sql.ErrNoRows → 404 at the handler
			}
			var doc map[string]any
			if err := json.Unmarshal(row.Document, &doc); err != nil {
				return api.Playback{}, err
			}
			mode, state, playURL, sections, voiceovers, stateReason, codecs, _, layout := w.media.Describe(itemID, doc)
			tok, _ := w.media.Issue(itemID, time.Now())
			return api.Playback{
				Mode: mode, State: state, PlayURL: playURL, StateReason: stateReason,
				Codecs: codecs, Layout: layout, Sections: sections, Voiceovers: voiceovers, Token: tok,
			}, nil
		},
	})
	srv := httptest.NewServer(web.Handler(apiH, web.Options{Media: w.media}))
	t.Cleanup(srv.Close)
	return srv.URL
}

// TestTvUnblockJoint is 3.1's acceptance floor: one real two-embedded-audio
// pack, served end-to-end, proves the whole contract the two groups built —
// the descriptor names the layout, the master composes the MSE-safe audio
// group, and the persist recorded both facts the descriptor reads.
func TestTvUnblockJoint(t *testing.T) {
	w := pbNewWorld(t)

	libRoot := t.TempDir()
	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA TV Unblock Joint")

	// The REAL dual-audio muxed source and the real lane over it (5 s against
	// the harness's 2 s head chunk: both pack phases run).
	fixtures := t.TempDir()
	mkv := tvuMakeTwoAudioFixture(t, fixtures, 5*time.Second)

	// The real enrich queue over gateNewQueue's PackItem (the gate pre-check,
	// the real Pack, Layout threaded into the outcome) and the real publish
	// replacement; the descriptor rides the mirrored closure's server.
	q := gateNewQueue(t, w)
	enqueue := w.pbEnqueue(q)
	baseURL := tvuServer(t, w)

	pmaSeedItem(t, w, libID, "tvu_a", "Dual Audio.mkv", mkv, tvuTwoAudioFacts(), "",
		map[string]any{"state": stream.StateNone})

	// --- the real pack: enqueue → the lane's success persist -----------------
	if err := enqueue("tvu_a"); err != nil {
		t.Fatalf("enqueue tvu_a: %v", err)
	}
	streams := pbAwaitStreams(t, w.st, "tvu_a", stream.StateComplete, 60*time.Second)
	pbAwaitIdle(t, q, 30*time.Second)
	nonce, _ := streams["nonce"].(string)
	if nonce == "" {
		t.Fatalf("persisted streams missing nonce: %v", streams)
	}
	// The persist wrote BOTH records itself — never seeded (that IS the
	// contract: publish → persist → descriptor): the current rule version and
	// the lane's layoutName over two embedded audio streams.
	if v, ok := streams["master"].(float64); !ok || v != float64(enrich.MasterRuleVersion) {
		t.Fatalf("persisted namespace carries master %v, want the current rule version %d (the success persist's write)",
			streams["master"], enrich.MasterRuleVersion)
	}
	if l, _ := streams["layout"].(string); l != "rendition" {
		t.Fatalf("persisted namespace carries layout %q, want \"rendition\" (the total-audio layout rule: 2 embedded, 0 sidecars)", l)
	}

	// --- the descriptor wire through the real router -------------------------
	status, body, _ := pbDo(t, w.client, http.MethodGet, baseURL+"/api/v1/items/tvu_a/playback", w.token, nil)
	if status != http.StatusOK {
		t.Fatalf("descriptor: status %d, want 200 (body=%s)", status, body)
	}
	var d tvuDescriptor
	if err := json.Unmarshal(body, &d); err != nil {
		t.Fatalf("decode descriptor: %v (body=%s)", err, body)
	}
	if d.Mode != stream.ModeHls || d.State != stream.StateComplete {
		t.Fatalf("descriptor = mode %q state %q, want hls/complete", d.Mode, d.State)
	}
	if !strings.HasPrefix(d.PlayURL, pmaMediaPrefix+"tvu_a/"+nonce+"/index.m3u8?token=") {
		t.Fatalf("play URL = %q, want the persisted nonce's master playlist with a token", d.PlayURL)
	}
	// The layout field rides the wire BESIDE the codecs record — present and
	// exactly "rendition" on this hls answer: the one field the SPA's
	// direct-floor refusal keys on (Interfaces 1/6; omitempty elsewhere).
	if d.Layout == nil {
		t.Fatalf("hls descriptor carries no layout key — the SPA refusal cannot classify: %s", body)
	}
	if string(d.Layout) != `"rendition"` {
		t.Fatalf("descriptor layout = %s, want \"rendition\"", d.Layout)
	}
	served := pmaCodecsWire(t, d.Codecs)
	if len(served) != 2 || !strings.HasPrefix(served[0], "avc1.") || served[1] != "mp4a.40.2" {
		t.Fatalf("descriptor codecs = %v, want [avc1.*, mp4a.40.2] (video first, deduped audio)", served)
	}

	// --- the build-root master's SERVED bytes --------------------------------
	// The SPA mounts this exact text: ONE video variant, the audio renditions
	// ONLY as EXT-X-MEDIA group members (MSE's one-track-per-type rule never
	// sees a second audio stream on the variant).
	token, _ := w.media.Issue("tvu_a", time.Now())
	master := pmaGetMedia(t, w, d.PlayURL, token)
	v := pmaParseMaster(string(master))
	if len(v.streamInf) != 1 {
		t.Fatalf("master carries %d EXT-X-STREAM-INF variants, want exactly ONE video variant:\n%s", len(v.streamInf), master)
	}
	if len(v.uris) != 1 {
		t.Fatalf("master carries %d URI lines, want exactly ONE (no audio rendition appears as a variant):\n%s", len(v.uris), master)
	}
	vi := v.streamInf[0]
	if got := pmaAttr(vi, "CODECS"); !strings.HasPrefix(got, "avc1.") || strings.Contains(got, "mp4a") {
		t.Fatalf("variant line CODECS = %q, want the video-only composition (audio rides EXT-X-MEDIA only)", got)
	}
	if pmaAttr(vi, "AUDIO") != "aud" {
		t.Fatalf("variant line AUDIO = %q, want the aud group", pmaAttr(vi, "AUDIO"))
	}
	if pmaAttr(vi, "RESOLUTION") != "128x72" {
		t.Fatalf("variant line RESOLUTION = %q, want the probed 128x72", pmaAttr(vi, "RESOLUTION"))
	}
	if !strings.Contains(vi, "BANDWIDTH=") {
		t.Fatalf("variant line carries no BANDWIDTH: %s", vi)
	}
	if !strings.Contains(v.uris[0], "rend0/index.m3u8?token="+token) {
		t.Fatalf("master URI line = %q, want the tokenized rend0 variant playlist", v.uris[0])
	}
	// The EXT-X-MEDIA group carries BOTH embedded audio renditions with unique
	// NAMEs (no language facts in the fixture — the stable Audio K ordinals)
	// and exactly ONE DEFAULT=YES riding the AAC-first rule's first rendition
	// in source order; every other rendition stays selectable, never default.
	if len(v.media) != 2 {
		t.Fatalf("master carries %d EXT-X-MEDIA renditions, want BOTH embedded audio streams:\n%s", len(v.media), master)
	}
	first, second := v.media[0], v.media[1]
	if pmaAttr(first, "NAME") != "Audio 1" || pmaAttr(second, "NAME") != "Audio 2" {
		t.Fatalf("EXT-X-MEDIA NAMEs = %q / %q, want the unique stable ordinals (GROUP-ID NAMEs must not collide)",
			pmaAttr(first, "NAME"), pmaAttr(second, "NAME"))
	}
	for _, ln := range []string{first, second} {
		if pmaAttr(ln, "TYPE") != "AUDIO" || pmaAttr(ln, "GROUP-ID") != "aud" {
			t.Fatalf("rendition line %s, want TYPE=AUDIO GROUP-ID=aud", ln)
		}
	}
	if n := strings.Count(string(master), "DEFAULT=YES"); n != 1 {
		t.Fatalf("master carries %d DEFAULT=YES, want exactly ONE:\n%s", n, master)
	}
	if pmaAttr(first, "DEFAULT") != "YES" || pmaAttr(second, "DEFAULT") != "NO" {
		t.Fatalf("DEFAULT ride = %q / %q, want the AAC-first rule's first rendition (both embedded streams are aac → source order)",
			pmaAttr(first, "DEFAULT"), pmaAttr(second, "DEFAULT"))
	}
	if pmaAttr(first, "AUTOSELECT") != "YES" || pmaAttr(second, "AUTOSELECT") != "YES" {
		t.Fatalf("AUTOSELECT = %q / %q, want YES on both (selectable, one default)",
			pmaAttr(first, "AUTOSELECT"), pmaAttr(second, "AUTOSELECT"))
	}
	if pmaAttr(first, "URI") != "rend1/index.m3u8?token="+token || pmaAttr(second, "URI") != "rend2/index.m3u8?token="+token {
		t.Fatalf("EXT-X-MEDIA URIs = %q / %q, want the tokenized rend1/rend2 playlists (self-authorizing bytes)",
			pmaAttr(first, "URI"), pmaAttr(second, "URI"))
	}
	// The group members SERVE: both audio renditions resolve through the media
	// surface the SPA would hand hls.js.
	for _, uri := range []string{pmaAttr(first, "URI"), pmaAttr(second, "URI")} {
		pl := pmaGetMedia(t, w, pbPlaylistURI(d.PlayURL, uri), token)
		if !strings.Contains(string(pl), "#EXTM3U") {
			t.Fatalf("audio rendition %s served no playlist:\n%s", uri, pl)
		}
	}
}
